const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const state = { completed:new Set(), guidedIndex:0, mock:null, mockIndex:0, mockSeconds:1080, mockTimerId:null, lessonSeconds:0 };

const toolkit = [
  {icon:'➕',title:'Develop an answer',items:['The main reason is…','One important point is…','For example…','This means that…','In my experience…']},
  {icon:'⏱',title:'Buy thinking time',items:['That’s an interesting question.','Let me think for a moment.','I’d say the main point is…','There are two things to consider.']},
  {icon:'❓',title:'Clarify',items:['Could you repeat the last part, please?','Do you mean…?','If I understand correctly…','Could you clarify what you mean by…?']},
  {icon:'🔁',title:'Repair & rephrase',items:['Let me rephrase that.','What I mean is…','A better way to explain it is…','Sorry, I meant…']},
  {icon:'🤝',title:'Interact',items:['How does that sound?','Would that work for you?','What would you prefer?','Could you confirm that?']},
  {icon:'🧭',title:'Solve a problem',items:['The first thing I would do is…','One option would be…','To avoid further delay…','I suggest that we…']},
  {icon:'⚖️',title:'Give an opinion',items:['From my point of view…','I can see both sides.','The main advantage is…','However, we also need to consider…']},
  {icon:'✅',title:'Close clearly',items:['So, just to confirm…','To sum up…','The next step is…','I’ll follow up by…']}
];

const scenarios = [
  // PART 1 — INTRODUCTION
  {id:'i1',stage:'intro',sector:'General',level:'A2+',title:'Your job',prompt:'What do you do?',follow:['What are your main responsibilities?','What do you enjoy most about your work?'],m1:'I work in administration. I organise documents, answer emails and help colleagues with appointments. I use English sometimes when I communicate with international contacts.',m2:'I work in administration for a medium-sized company. My main responsibilities include coordinating documents, answering internal and external requests, and organising appointments. I particularly enjoy solving practical problems because every day is slightly different. I also use English when I communicate with international partners.'},
  {id:'i2',stage:'intro',sector:'General',level:'A2+',title:'Your workplace',prompt:'Describe your workplace.',follow:['Do you work alone or in a team?','What makes your workplace efficient?'],m1:'I work in an office with a small team. We have an open-plan area and two meeting rooms. I usually work on site, but I sometimes work from home.',m2:'I work in an open-plan office with a team of about ten people. We also have several meeting rooms for client calls and project meetings. I mainly work on site because collaboration is easier, although I occasionally work remotely when I need to focus on individual tasks.'},
  {id:'i3',stage:'intro',sector:'General',level:'B1',title:'Typical working day',prompt:'What does a typical working day look like for you?',follow:['What is usually the busiest part of the day?','How do you organise your priorities?'],m1:'I usually start by checking my emails and priorities. Then I work on current tasks and speak with colleagues or clients. In the afternoon, I often have meetings and prepare the next day.',m2:'I normally begin by checking urgent emails and reviewing my priorities. I then focus on the most time-sensitive tasks before attending meetings or speaking with clients. The afternoon is often more collaborative, so I keep quieter work for the morning. Before finishing, I review what is still outstanding and plan the following day.'},
  {id:'i4',stage:'intro',sector:'Projects',level:'B1',title:'Recent project',prompt:'Tell me about a recent project or important task.',follow:['What was your role?','Was there a problem and how did you handle it?'],m1:'Recently, I worked on a project to update a customer process. My role was to collect information and test the new procedure. We had a delay, but we reorganised the priorities and finished the project.',m2:'Recently, I contributed to a project to redesign part of our customer process. I was responsible for collecting requirements, coordinating feedback and testing the updated procedure. We experienced a delay because some information arrived late, so I helped reprioritise the tasks and communicate a revised timeline. In the end, we delivered the new process successfully.'},
  {id:'i5',stage:'intro',sector:'General',level:'B1',title:'Professional strengths',prompt:'What are your main professional strengths?',follow:['Can you give an example?','Which skill would you still like to improve?'],m1:'I am organised and calm when there is a problem. For example, I can manage several requests and decide which one is most urgent. I would like to improve my English confidence.',m2:'I would say my main strengths are organisation, reliability and staying calm under pressure. For example, when several urgent requests arrive at the same time, I can quickly prioritise them and keep the people involved informed. One skill I would still like to develop is speaking English more spontaneously in meetings.'},
  {id:'i6',stage:'intro',sector:'General',level:'B1',title:'Change at work',prompt:'Describe a change that affected your work.',follow:['How did you adapt?','Was the change positive in the end?'],m1:'My company introduced a new software system. At first it was difficult because we had to change our habits. After some training, I became more comfortable and it is now faster.',m2:'A major change in my work was the introduction of a new software platform. Initially, it slowed us down because we had to learn a different process while continuing our normal workload. I attended training, practised with real cases and shared tips with colleagues. After a few weeks, the transition became much easier and the system now saves us time.'},
  {id:'i7',stage:'intro',sector:'Remote/Meetings',level:'B1',title:'Working with others',prompt:'How do you communicate with colleagues or clients?',follow:['Which communication channel do you prefer?','What can make communication difficult?'],m1:'I use email, phone calls and video meetings. For urgent problems, I prefer a phone call because it is faster. For important information, I also send an email so there is a written record.',m2:'I adapt the communication channel to the situation. For urgent or sensitive issues, I prefer a call because we can clarify things immediately. For decisions, deadlines or technical details, I follow up in writing so everyone has the same information. Video meetings are useful when several people need to discuss a topic together.'},
  {id:'i8',stage:'intro',sector:'General',level:'B1+',title:'Professional goal',prompt:'What professional goal are you working towards?',follow:['Why is this goal important?','What are you doing to achieve it?'],m1:'I want to become more confident using English at work. It is important because I have more international contacts now. I practise speaking and learn useful vocabulary for my job.',m2:'One of my main professional goals is to become fully comfortable working in English. My role is becoming more international, so I need to participate in meetings and handle unexpected questions without translating everything in my head. I am working on this through regular speaking practice, sector-specific vocabulary and realistic role-plays.'},
  {id:'i9',stage:'intro',sector:'General',level:'B2',title:'Decision you made',prompt:'Tell me about an important professional decision you made.',follow:['What alternatives did you consider?','What did you learn from the decision?'],m1:'I decided to reorganise the order of several tasks because one project had become urgent. I compared the deadlines and spoke with the people concerned before changing the plan.',m2:'A recent decision involved reprioritising several projects when a client deadline suddenly became critical. I first assessed the operational impact, then spoke with the teams whose work would be delayed. I chose to reallocate resources temporarily because it protected the most important commitment while keeping the other stakeholders informed. It reminded me that a good decision also requires clear communication.'},
  {id:'i10',stage:'intro',sector:'General',level:'B2',title:'A professional challenge',prompt:'Describe a professional challenge and what you learned from it.',follow:['What would you do differently next time?','How did other people react?'],m1:'I once had to manage a project with incomplete information. I asked more questions and created a simple list of priorities. I learned that it is better to clarify early than to make assumptions.',m2:'One significant challenge was managing a project when the requirements were still changing. At first, the team was losing time because different people were working from different assumptions. I organised a short clarification meeting, documented the agreed priorities and introduced regular checkpoints. The experience taught me that uncertainty is manageable if communication is frequent and decisions are made visible.'},

  // PART 2 — ROLE PLAY
  {id:'r1',stage:'roleplay',sector:'IT',level:'B1',title:'Ask for software training',prompt:'You have started a new job and must use software you do not know. Call IT, explain your need and organise training.',follow:['I can only offer training next Thursday. Does that work?','What exactly do you need to learn?'],m1:'Hello, I’m calling because I need some help with the new software. I have to use it for my daily work, but I have not received training yet. Would it be possible to organise a training session? Next Thursday could work for me. I mainly need help with the basic functions and reporting.',m2:'Hi, I’m getting in touch because my new role requires me to use the reporting software, and I’m not yet confident with it. I can manage the basic navigation, but I need training on creating reports, updating records and correcting errors. Would it be possible to arrange a practical session? Next Thursday should be fine. Could you also let me know whether I need to install anything beforehand?'},
  {id:'r2',stage:'roleplay',sector:'Customer service',level:'B1',title:'Handle a complaint',prompt:'A customer is unhappy because an order arrived late. Apologise, find out what happened and propose a solution.',follow:['I needed the order yesterday. What can you do now?','How can I be sure this will not happen again?'],m1:'I’m sorry about the delay. Let me check what happened with your order. I understand that you needed it yesterday. I can arrange priority delivery today and confirm the new delivery time by email. Would that help?',m2:'I’m very sorry the order did not arrive when expected, and I understand the inconvenience this has caused. Let me check the tracking information and confirm exactly where the delay occurred. As an immediate solution, I can arrange priority delivery and send you a confirmed time today. I’ll also review the cause with our logistics team so we can prevent the same issue from happening again. Would that solution be acceptable?'},
  {id:'r3',stage:'roleplay',sector:'Logistics',level:'B1+',title:'Supplier delay',prompt:'A supplier says an urgent delivery will be three days late. Explain the impact and negotiate a practical alternative.',follow:['We cannot deliver the full order earlier.','We may be able to send 40% tomorrow.'],m1:'Three days will be difficult because our production depends on this delivery. Could you send part of the order earlier? If you can send 40% tomorrow, that would help us continue. Please confirm the quantity and delivery time today.',m2:'A three-day delay would have a significant impact because the materials are needed for production tomorrow. If the full order cannot arrive earlier, could we look at a partial shipment? You mentioned that 40% may be available tomorrow; that would allow us to protect the most urgent work. Could you confirm the exact quantity, dispatch time and expected arrival by the end of today?'},
  {id:'r4',stage:'roleplay',sector:'Remote/Meetings',level:'A2+',title:'Reschedule a meeting',prompt:'A colleague cannot attend tomorrow’s meeting. Find another time and confirm what should happen with the documents.',follow:['I am free on Friday morning but not Thursday.','Should I update the agenda?'],m1:'Friday morning is fine for me. Could we meet at 10 a.m.? Yes, please update the agenda and send the new version before the meeting. I will confirm the time with the other people.',m2:'Friday morning should work. Would 10 a.m. be convenient for you? Please update the agenda with the two new points and send the revised version to everyone beforehand. I’ll check availability with the rest of the team and confirm the new invitation this afternoon.'},
  {id:'r5',stage:'roleplay',sector:'Projects',level:'B1',title:'Explain a delay',prompt:'A manager asks why a project is late. Explain the cause, the current situation and the recovery plan.',follow:['Why was this not identified earlier?','What do you need from me?'],m1:'The project is late because we received important information two days later than planned. We have finished the first part, but testing is still in progress. We are reorganising the tasks and expect to finish on Friday. I need confirmation of one priority from you.',m2:'The main reason for the delay is that the technical information needed for testing arrived two days later than expected. The development work is complete, but final testing is still in progress. We have reorganised the remaining tasks and believe Friday is realistic. To keep that date, I need you to confirm which of the two final features should take priority.'},
  {id:'r6',stage:'roleplay',sector:'General',level:'B1',title:'Explain a procedure',prompt:'A new colleague asks how to handle an urgent customer request. Explain the steps clearly and check understanding.',follow:['What should I do if the manager is unavailable?','Do I need to document the request?'],m1:'First, check the customer details and understand what is urgent. Then contact the person responsible and explain the situation. If the manager is unavailable, contact the duty supervisor. Yes, record the request in the system. Is that clear?',m2:'First, verify the customer details and identify exactly what makes the request urgent. Next, record the case in the system and contact the person responsible. If the manager is unavailable, escalate it to the duty supervisor rather than waiting. Make sure the action and any promised deadline are documented. Would you like me to show you where to enter the information?'},
  {id:'r7',stage:'roleplay',sector:'Finance',level:'B1+',title:'Payment discrepancy',prompt:'A client says an invoice amount is incorrect. Clarify the problem and agree on the next step.',follow:['The total is €450 higher than our purchase order.','I need a corrected invoice today.'],m1:'Thank you for telling me. Could you confirm the purchase order number? I will compare it with the invoice and check the extra €450. If there is an error, I will ask our finance team to issue a corrected invoice today and send it to you.',m2:'Thanks for flagging this. Let me make sure I understand: the invoice total is €450 higher than the amount on your purchase order. Could you confirm the PO number and the line concerned? I’ll cross-check the details immediately. If the discrepancy is on our side, I’ll ask finance to issue a corrected invoice today and I’ll send you written confirmation once it has been processed.'},
  {id:'r8',stage:'roleplay',sector:'HR',level:'B1',title:'Request training',prompt:'Speak to your manager about a training course you would like to attend. Explain why it is useful and discuss timing.',follow:['The budget is limited. Why is this a priority?','Could you attend next quarter instead?'],m1:'I would like to attend this training because I need the skill for my current projects. It would help me work more independently. I understand the budget is limited. If next quarter is easier, I can attend then.',m2:'I’d like to discuss a training course that is directly related to my current projects. It would help me handle more of the work independently and reduce the number of issues we need to escalate. I understand the budget is tight, so I’m flexible on timing. If next quarter is more realistic, I’d be happy to plan it then, provided we can reserve a place.'},
  {id:'r9',stage:'roleplay',sector:'Sales',level:'B1+',title:'Handle a client objection',prompt:'A client says your proposal is too expensive. Clarify their concern and defend the value without becoming aggressive.',follow:['Your competitor is 15% cheaper.','Can you reduce the price?'],m1:'I understand that price is important. Could you tell me which part seems too expensive? Our offer includes support and faster delivery, which are not included in the cheaper option. I can review the package and see if we can adjust the scope.',m2:'I understand the price difference is significant. Before discussing a reduction, could I check whether you are comparing the same level of service? Our proposal includes implementation support, priority assistance and a shorter delivery time. Those elements reduce operational risk after purchase. That said, I can review the scope with you and see whether there are features we can adjust without affecting the essential service.'},
  {id:'r10',stage:'roleplay',sector:'Customer service',level:'B1',title:'Wrong order',prompt:'A customer received the wrong product. Confirm the problem, organise a replacement and explain what happens next.',follow:['Do I have to pay for the return?','When will the replacement arrive?'],m1:'I’m sorry about the mistake. You will not have to pay for the return. I can arrange a prepaid return label and send the correct product today. It should arrive within two working days.',m2:'I’m sorry you received the wrong item. I’ve checked the order and I can see the mismatch. We’ll organise the return at no cost to you and send a prepaid label by email. I can also release the correct item today, with delivery expected within two working days. I’ll send you the tracking details as soon as it leaves our warehouse.'},
  {id:'r11',stage:'roleplay',sector:'Remote/Meetings',level:'B1+',title:'Video-call misunderstanding',prompt:'During a video meeting, you realise two teams understood the deadline differently. Clarify the misunderstanding and agree on one timeline.',follow:['We thought the deadline was Friday.','The other team needs until Tuesday.'],m1:'I think we have two different deadlines, so let’s clarify. Our team understood Friday, but the other team needs until Tuesday. Could we agree that the first version is due Friday and the final version Tuesday?',m2:'It sounds as though we are working with two different interpretations of the deadline. Our team understood that Friday was the final date, while your team is planning for Tuesday. To avoid further confusion, could we use Friday for the first complete version and Tuesday for final validation? If everyone agrees, I’ll summarise the two milestones in writing after the call.'},
  {id:'r12',stage:'roleplay',sector:'Projects',level:'B2',title:'Negotiate priorities',prompt:'Two managers both say their task is urgent, but your team cannot complete both. Clarify priorities and negotiate a realistic plan.',follow:['My task affects a key client.','The other task is linked to a legal deadline.'],m1:'Both tasks are important, but we need to compare the consequences. The legal deadline cannot move, so I suggest we protect that first. For the client task, we could deliver part of it now and complete the rest afterwards.',m2:'I understand why both requests are being treated as urgent, but with the current capacity we need a clear priority decision. The legal deadline carries a fixed compliance risk, whereas the client task has more flexibility in how it is delivered. My recommendation would be to protect the legal deadline and agree a phased delivery for the client work. If that is acceptable, I can provide the client with an interim result and a firm date for completion.'},
  {id:'r13',stage:'roleplay',sector:'IT',level:'B1+',title:'System outage',prompt:'A colleague cannot access an essential system. Ask diagnostic questions and propose immediate alternatives.',follow:['I restarted my computer and it still does not work.','I need the file for a client call in 20 minutes.'],m1:'Have you checked whether the problem is only on your computer or for everyone? Since restarting did not help, I can contact IT support. For your call, I can send you the latest exported file so you can continue.',m2:'Let’s first identify whether this is a local issue or a wider outage. Since you have already restarted, could you check whether you can access the web version? I’ll raise an urgent ticket with IT at the same time. Because your client call starts in 20 minutes, I can also send you the latest exported file so you have a temporary workaround.'},
  {id:'r14',stage:'roleplay',sector:'HR',level:'B1+',title:'Give constructive feedback',prompt:'A colleague regularly sends incomplete information. Explain the impact and agree on a better way of working.',follow:['I didn’t realise it was causing a problem.','What information do you need from me?'],m1:'I wanted to mention something about the information you send. Sometimes important details are missing, so I have to contact you again and the process takes longer. Could we use a short checklist before you send it?',m2:'I’d like to discuss one thing that could make our work smoother. Some of the requests I receive are missing key details, which means I have to come back to you and it delays the next step. I don’t think it’s intentional, so perhaps we could agree on a simple checklist with the information needed each time. Would that be practical for you?'},
  {id:'r15',stage:'roleplay',sector:'Tourism',level:'B1',title:'Guest problem',prompt:'A hotel guest says the room is too noisy and wants a solution. Respond professionally and offer alternatives.',follow:['I have an early meeting tomorrow.','I do not want to pay more.'],m1:'I’m sorry the room is too noisy. I understand you have an early meeting. I can check whether we have a quieter room available at the same price. If not, I can offer another solution.',m2:'I’m sorry the noise is affecting your stay, especially with an early meeting tomorrow. Let me check our availability immediately. If we have a quieter room in the same category, I can move you at no extra charge. If that is not available, I’ll see what alternative we can offer so you can rest properly tonight.'},
  {id:'r16',stage:'roleplay',sector:'Healthcare',level:'B1',title:'Appointment change',prompt:'A patient or client appointment must be moved because of an unexpected absence. Explain the situation and find an acceptable alternative.',follow:['I already changed my schedule for this appointment.','What is the earliest alternative?'],m1:'I’m very sorry, but we need to move your appointment because the professional is unexpectedly absent. I understand this is inconvenient. The earliest alternative is tomorrow at 11 a.m. Would that be possible?',m2:'I’m very sorry, but we need to reschedule your appointment due to an unexpected absence today. I appreciate that you may already have reorganised your schedule, so I’d like to find the earliest possible alternative. I can offer tomorrow at 11 a.m. or, if that is difficult, I can check for another priority slot. Which option would work best for you?'},
  {id:'r17',stage:'roleplay',sector:'Industry',level:'B2',title:'Safety incident',prompt:'A minor safety incident has occurred. Brief a manager on what happened, immediate action taken and what should happen next.',follow:['Was anyone injured?','Should production stop?'],m1:'There was a minor incident near the loading area. No one was injured. We stopped activity in that area and checked the equipment. I recommend keeping the area closed until the safety check is complete.',m2:'We had a minor safety incident in the loading area when a piece of equipment moved unexpectedly. No one was injured, but we stopped activity there immediately and secured the equipment. At this stage, the rest of production can continue, but I recommend keeping that specific area closed until maintenance and the safety team have completed their checks. I’ll document the incident and confirm when the area can reopen.'},
  {id:'r18',stage:'roleplay',sector:'Projects',level:'B1+',title:'Project handover',prompt:'You are handing a project to a colleague before leave. Explain status, priorities, risks and what may require action.',follow:['What should I do if the client asks for a change?','Which task is the highest priority?'],m1:'The project is on schedule. The main priority is the client validation on Wednesday. The only risk is that one supplier has not confirmed the final delivery. If the client requests a change, please record it and contact the project manager before promising anything.',m2:'The project is broadly on schedule. Your main priority is to secure the client validation on Wednesday because the next phase depends on it. The main risk is the supplier confirmation, which is still outstanding. If the client requests any scope change, please document the request and check it with the project manager before committing to a new date or cost. I’ve listed all contacts in the handover note.'},
  {id:'r19',stage:'roleplay',sector:'Sales',level:'B2',title:'Negotiate a deadline',prompt:'A client wants delivery two weeks earlier than planned. Explore what is possible without promising something unrealistic.',follow:['We really need the earlier date.','Could you at least deliver the essential part first?'],m1:'Two weeks earlier may not be possible for the full project. I need to check our capacity before confirming. We could perhaps deliver the essential part first and complete the rest on the original date.',m2:'I understand why the earlier date matters, but I don’t want to commit to something we cannot deliver reliably. Bringing the full project forward by two weeks would be difficult with the current resources. One option would be to identify the essential deliverables and release those first, while keeping the remaining work on the original schedule. If you tell me which elements are critical, I can check what is feasible today.'},
  {id:'r20',stage:'roleplay',sector:'General',level:'B1',title:'Missing document',prompt:'You need an important document from a colleague before a deadline. Ask for it, explain the impact and agree on a time.',follow:['I thought someone else was sending it.','I can send it at the end of the day.'],m1:'I still need the document for tomorrow’s deadline. I understand there was a misunderstanding. End of the day is a little late because I need time to check it. Could you send it by 3 p.m.?',m2:'I’m still missing the document needed for tomorrow’s deadline. I understand there was some confusion about who was responsible for sending it. If it arrives only at the end of the day, I won’t have enough time to review it properly. Would it be possible to send it by 3 p.m.? That would give me enough time to check everything and come back to you if anything is missing.'},
  {id:'r21',stage:'roleplay',sector:'Travel/Logistics',level:'B1',title:'Travel disruption',prompt:'A business trip is disrupted by a cancelled train or flight. Contact a colleague and reorganise the meeting.',follow:['The client can only meet today.','Could you join remotely instead?'],m1:'My train has been cancelled, so I will not arrive in time. If the client can only meet today, I can join by video instead. Could you send me the meeting link and explain the situation to the client?',m2:'My train has been cancelled and the alternative service will not get me there in time for the meeting. Since the client is only available today, the best solution may be for me to join remotely rather than postpone. Could you send me the video link and let the client know about the disruption? I’ll connect early to make sure the technical setup works.'},
  {id:'r22',stage:'roleplay',sector:'Remote/Meetings',level:'B2',title:'Manage disagreement in a meeting',prompt:'Two colleagues strongly disagree about a project approach. Help clarify the issue and move the meeting towards a decision.',follow:['Neither option seems acceptable to the other person.','How would you decide?'],m1:'I think we need to separate the two concerns. One option is faster, but the other reduces risk. Could we agree on the most important criterion first and then compare the two options against it?',m2:'We seem to be debating two different priorities rather than just two solutions. One proposal optimises speed, while the other focuses on reducing risk. Before choosing, could we agree on which criterion is most important for this project? We could then compare both options against the same criteria—time, cost and risk—and make the decision on that basis rather than continuing the disagreement.'},
  {id:'r23',stage:'roleplay',sector:'Customer service',level:'B2',title:'Escalated complaint',prompt:'A long-standing customer is angry after several errors. De-escalate the conversation, take ownership and propose a credible recovery plan.',follow:['This is the third time this has happened.','Why should I continue working with you?'],m1:'I understand why you are frustrated, especially because this is not the first problem. I want to take responsibility for resolving it. I will review the three incidents, give you one contact person and confirm a recovery plan today.',m2:'I completely understand why your confidence has been affected, particularly because this is the third issue rather than an isolated mistake. I don’t want to minimise that. I’d like to take ownership of the case, review the previous incidents and give you one point of contact so you do not have to repeat the situation. I will send you a concrete recovery plan today, including the immediate correction and the preventive actions. Then I’d like to review it with you personally.'},
  {id:'r24',stage:'roleplay',sector:'General',level:'B1+',title:'Unexpected request',prompt:'Your manager asks you to take on urgent work, but you already have a full workload. Explain the situation and negotiate priorities.',follow:['This new task must be done today.','Which of your current tasks could move?'],m1:'I can take the new task, but I will need to move something else. I currently have two deadlines today. Could we decide which one can be postponed so I can focus on the urgent request?',m2:'I can take responsibility for the urgent task, but with my current workload I would need to reprioritise something else rather than simply add it on top. I have two existing deadlines today, so could we review which of those has the least impact if it moves? Once we agree on the priority, I can communicate the revised timing to the people concerned.'},

  // PART 3 — DISCUSSION
  {id:'d1',stage:'discussion',sector:'Remote/Meetings',level:'B1+',title:'Remote work',prompt:'What should a company consider when introducing remote work?',follow:['What are the main advantages?','What risks should managers anticipate?'],m1:'A company should think about communication, equipment and clear rules. Remote work can save travel time and help concentration, but people can also feel isolated. Regular meetings and clear objectives are important.',m2:'When introducing remote work, a company needs to consider technology, communication, management expectations and employee wellbeing. The advantages include flexibility and less commuting, but there are also risks such as isolation, weaker informal communication and unclear boundaries. In my view, the best approach is a clear framework with appropriate equipment, measurable objectives and regular contact rather than simply allowing people to work from home without structure.'},
  {id:'d2',stage:'discussion',sector:'IT',level:'B2',title:'Artificial intelligence at work',prompt:'How should companies use artificial intelligence responsibly?',follow:['Which tasks should remain human?','What are the biggest risks?'],m1:'AI can save time for repetitive tasks, but companies should check the results and protect confidential information. Important decisions should still involve people.',m2:'AI can be extremely useful for repetitive analysis, drafting and information retrieval, but responsible use requires clear boundaries. Companies need to protect confidential data, verify outputs and make sure employees understand when human judgement is still necessary. I would be particularly cautious with decisions affecting people, safety or major financial commitments, because efficiency should not replace accountability.'},
  {id:'d3',stage:'discussion',sector:'General',level:'B1',title:'Training at work',prompt:'Why is continuous professional training important?',follow:['Who should be responsible for training?','Is online training as effective as face-to-face training?'],m1:'Training is important because jobs and technology change. Employees need new skills to work efficiently. I think the company and the employee should both take responsibility.',m2:'Continuous training matters because roles, technology and customer expectations keep changing. It helps employees stay effective and can also improve motivation because people see opportunities to develop. Responsibility should be shared: the company should provide relevant opportunities, while employees need to engage actively and apply what they learn.'},
  {id:'d4',stage:'discussion',sector:'Customer service',level:'B1+',title:'Good customer service',prompt:'What makes customer service effective?',follow:['Is speed more important than personal contact?','How should complaints be handled?'],m1:'Good customer service means listening, responding quickly and giving clear information. Speed is important, but the customer also needs to feel understood.',m2:'Effective customer service combines speed, accuracy and empathy. A fast answer is not useful if it does not solve the customer’s problem, so the first priority should be understanding the situation correctly. When a complaint occurs, staff should acknowledge the impact, take ownership of the next step and communicate a realistic solution rather than making promises they cannot keep.'},
  {id:'d5',stage:'discussion',sector:'General',level:'B1+',title:'Teamwork',prompt:'What makes a team work well?',follow:['How should a team deal with disagreement?','What role should a manager play?'],m1:'A good team needs clear communication, trust and clear responsibilities. Disagreement is normal, but people should focus on the problem and not the person.',m2:'Strong teams usually have clear objectives, defined responsibilities and enough trust for people to raise problems early. Disagreement can actually improve decisions if it stays focused on evidence and solutions rather than personalities. A manager should create that environment, remove obstacles and make sure decisions are clear without controlling every detail.'},
  {id:'d6',stage:'discussion',sector:'General',level:'B1+',title:'Work-life balance',prompt:'What can companies do to support a healthy work-life balance?',follow:['Should working hours be flexible?','Can flexibility create problems?'],m1:'Companies can offer flexible hours, realistic workloads and clear rules about availability. Flexibility is useful, but teams still need common times to work together.',m2:'Companies can support work-life balance through realistic workloads, flexible arrangements and clear expectations about availability. Flexibility can improve motivation and reduce commuting pressure, but it needs structure; otherwise, people may feel they have to be available all the time. I think the key is giving employees autonomy while maintaining shared team rules.'},
  {id:'d7',stage:'discussion',sector:'General',level:'B2',title:'Managing change',prompt:'Why do employees sometimes resist change, and how should companies respond?',follow:['Is resistance always negative?','What makes change communication credible?'],m1:'People can resist change because they are worried about losing habits or skills. Companies should explain the reason for the change and give training and support.',m2:'Resistance often comes from uncertainty rather than from opposition to the idea itself. Employees may worry about workload, competence, job security or simply losing familiar routines. I do not think resistance is always negative; it can reveal practical risks that management has missed. The most credible change communication explains the reason, the impact, what is still uncertain and how employees will be supported.'},
  {id:'d8',stage:'discussion',sector:'General',level:'B1+',title:'Meetings',prompt:'What makes a professional meeting useful rather than a waste of time?',follow:['When should a meeting be replaced by an email?','How should decisions be recorded?'],m1:'A useful meeting needs a clear objective and the right people. If the purpose is only to share simple information, an email may be better. Decisions should be written down with actions and deadlines.',m2:'A meeting is useful when interaction is necessary—when people need to decide, solve, challenge or coordinate something together. If information only needs to be distributed, an email or shared document is often more efficient. Good meetings should end with clear decisions, named actions, owners and deadlines so that the conversation leads to something concrete.'},
  {id:'d9',stage:'discussion',sector:'General',level:'B1+',title:'Intercultural communication',prompt:'What can make communication difficult in international teams?',follow:['Should everyone adapt to one communication style?','How can misunderstandings be reduced?'],m1:'People can have different communication styles and expectations. Some are more direct and others are more indirect. Teams should ask questions and confirm important information.',m2:'International teams can experience misunderstandings because expectations about directness, hierarchy, silence or disagreement are not always the same. I do not think everyone needs to adopt one identical style, but teams benefit from shared rules for important communication. Clarifying assumptions, summarising decisions and avoiding idioms when clarity matters can reduce unnecessary friction.'},
  {id:'d10',stage:'discussion',sector:'General',level:'B2',title:'Employee motivation',prompt:'What motivates people at work besides salary?',follow:['Is recognition important?','Can the same approach motivate everyone?'],m1:'People can be motivated by recognition, interesting work, flexibility and opportunities to learn. Different people have different priorities.',m2:'Salary matters, but motivation is also influenced by autonomy, recognition, meaningful work, development and the quality of management. The same approach will not motivate everyone because people are at different career stages and value different things. I think managers need to understand individual drivers while still creating fair and transparent conditions for the whole team.'},
  {id:'d11',stage:'discussion',sector:'Industry',level:'B1+',title:'Workplace safety',prompt:'How can a company build a strong safety culture?',follow:['Are procedures enough?','How should employees report mistakes or near misses?'],m1:'A company needs clear procedures, training and good equipment. Employees should be able to report problems without being afraid of blame.',m2:'Procedures and equipment are essential, but a real safety culture also depends on behaviour and communication. Employees need to feel comfortable reporting near misses before they become accidents. If every mistake leads to blame, people may hide information. Companies should investigate causes, correct unsafe systems and still be clear about individual responsibility when rules are deliberately ignored.'},
  {id:'d12',stage:'discussion',sector:'HR',level:'B2',title:'Recruitment',prompt:'What makes a recruitment process fair and effective?',follow:['How important are qualifications compared with experience?','Should companies use AI in recruitment?'],m1:'A fair process needs clear criteria and the same basic questions for candidates. Experience and qualifications are both useful, depending on the job.',m2:'A fair recruitment process begins with criteria that are directly connected to the role and are applied consistently. Qualifications can demonstrate knowledge, while experience shows how someone has used skills in practice, so the balance depends on the position. AI may help with administration or initial organisation, but I would be cautious about allowing automated tools to make decisions without transparency and human review.'},
  {id:'d13',stage:'discussion',sector:'General',level:'B1+',title:'Sustainability at work',prompt:'What practical actions can companies take to become more sustainable?',follow:['Do small actions really matter?','How can companies avoid greenwashing?'],m1:'Companies can reduce energy use, waste and unnecessary travel. Small actions matter if many people follow them. Companies should also measure results instead of only making claims.',m2:'Practical sustainability measures can include reducing energy consumption, improving procurement, limiting unnecessary travel and designing processes that create less waste. Small actions are useful when they are systematic, but companies should focus on the areas with the greatest real impact. To avoid greenwashing, targets should be measurable and progress should be reported transparently, including when results are below expectations.'},
  {id:'d14',stage:'discussion',sector:'Projects',level:'B2',title:'Risk versus speed',prompt:'When a project is urgent, how should a team balance speed and quality?',follow:['Is “good enough” sometimes acceptable?','Who should decide what risk is acceptable?'],m1:'Teams need to understand which quality requirements are essential and which details can wait. Sometimes a first version can be good enough if the risks are low.',m2:'Urgency should not mean treating every quality requirement as optional. The team needs to identify which standards protect safety, compliance or the customer outcome and therefore cannot be compromised. Other elements may be delivered in phases. A “good enough” first version can be reasonable when the risks are understood and reversible, but the acceptable level of risk should be agreed by the people accountable for the outcome.'},
  {id:'d15',stage:'discussion',sector:'Remote/Meetings',level:'B1+',title:'Hybrid meetings',prompt:'How can companies make hybrid meetings work well for both remote and in-room participants?',follow:['What technical problems are common?','How can remote people be included?'],m1:'Everyone needs good audio and a clear meeting structure. The chair should ask remote participants for their opinion and make sure documents are shared on screen.',m2:'Hybrid meetings often fail when the room becomes the centre of the conversation and remote participants become observers. Good audio is more important than impressive video, and everyone should have access to the same documents. The chair can actively invite remote participants to contribute, monitor chat and summarise side conversations that might otherwise exclude them.'},
  {id:'d16',stage:'discussion',sector:'Finance',level:'B2',title:'Cost reduction',prompt:'How should a company reduce costs without damaging long-term performance?',follow:['Where should cuts start?','What should companies avoid cutting?'],m1:'A company should first look for waste and inefficient processes. It should be careful about reducing training or important maintenance because this can create bigger costs later.',m2:'Cost reduction should begin with understanding what creates value and what creates avoidable waste. Cutting across every department equally may look fair, but it can damage critical capabilities. I would first target duplication, low-value processes and spending that does not support the strategy. I would be cautious about cutting maintenance, core skills or customer-facing capacity because short-term savings there can create much larger costs later.'},
  {id:'d17',stage:'discussion',sector:'Customer service',level:'B1+',title:'Automation and customer contact',prompt:'Should companies automate more customer service?',follow:['Which interactions can be automated?','When is a human essential?'],m1:'Automation is useful for simple questions and information that customers need quickly. A person is important for complex problems or when the customer is upset.',m2:'Automation works well for predictable, low-risk interactions such as order tracking, opening hours or basic account information. It can reduce waiting time and free staff for more complex work. However, customers should be able to reach a person when the situation involves emotion, exceptions, financial consequences or repeated failure, because those cases require judgement and trust.'},
  {id:'d18',stage:'discussion',sector:'General',level:'B2',title:'Leadership',prompt:'What makes someone an effective manager?',follow:['Should managers be experts in every task?','How should a manager deal with mistakes?'],m1:'A good manager communicates clearly, supports the team and makes decisions. They do not need to know every technical detail, but they need to understand the work.',m2:'An effective manager provides direction, creates clarity and gives people enough autonomy to do their work well. They do not need to be the strongest technical expert in every area, but they need enough understanding to ask good questions and make informed decisions. When mistakes happen, a manager should distinguish between a learning opportunity, a process problem and genuinely irresponsible behaviour rather than reacting in the same way to every error.'}
];

const guidedTasks = [
 {type:'Part 1 · Answer expansion',title:'Turn one sentence into a professional answer',prompt:'Examiner: “What do you do?” Give a direct answer, then add responsibilities and one example.',plan:['Direct answer','2 responsibilities','Concrete example','Natural finish'],hint:'Use: I work as/in… My main responsibilities include… For example…',m1:'I work in administration. I organise documents, answer emails and help with appointments. For example, I often prepare information before meetings.',m2:'I work in administration for a medium-sized company. My main responsibilities include coordinating documents, responding to internal requests and organising appointments. For example, before an important meeting I make sure the right documents and information are available for everyone.',fr:'Réponse directe + responsabilités + exemple concret. Évitez une réponse d’une seule phrase.',q:['Which answer best demonstrates your level?','I work in administration.','I work in administration, where I coordinate documents, respond to requests and prepare information for meetings.','Administration is my job.'],a:1,ex:'The strongest answer develops the role with responsibilities and a concrete context.'},
 {type:'Part 1 · Typical day',title:'Organise a clear description',prompt:'Describe a typical working day without listing random tasks.',plan:['Start of day','Main work','Interaction','End / priorities'],hint:'Use sequencing: I usually start by… Then… Later in the day… Before I finish…',m1:'I usually start by checking emails. Then I work on my main tasks and speak with colleagues. In the afternoon I often have meetings. Before I finish, I prepare the next day.',m2:'I normally start by checking urgent messages and reviewing my priorities. I then focus on tasks that require concentration before moving into calls or meetings later in the day. Before I finish, I check anything still outstanding and make a short plan for the following morning.',fr:'Utilisez des marqueurs de séquence pour éviter une simple liste.',q:['Which opening is clearest?','Every day is many things.','I usually start by checking urgent messages and reviewing my priorities.','I do emails, meetings, tasks.'],a:1,ex:'A clear sequence helps the examiner follow your answer and shows stronger control.'},
 {type:'Part 1 · Experience',title:'Tell a short professional story',prompt:'Describe a recent challenge. Give the situation, what you did and the result.',plan:['Situation','Problem','Action','Result / learning'],hint:'Use a mini-STARR: We had… I decided to… As a result… I learned…',m1:'We had a delay because information arrived late. I contacted the people involved and reorganised the tasks. We finished two days later and I learned to check critical information earlier.',m2:'On a recent project, key information arrived later than expected, which put our deadline at risk. I contacted the people involved, clarified what was still missing and reorganised the remaining work around the most urgent tasks. We finished two days later than planned, but avoided a larger delay. It taught me to identify critical dependencies much earlier.',fr:'Une petite histoire structurée montre beaucoup plus de compétences qu’une opinion générale.',q:['What should come after the situation?','A random second example','The action you took','A new topic'],a:1,ex:'A clear professional story moves from situation/problem to action and result.'},
 {type:'Interaction · Clarification',title:'Ask the examiner to clarify instead of freezing',prompt:'You did not fully understand the scenario instructions. Respond naturally.',plan:['Signal','Specific clarification','Confirm'],hint:'Could you repeat…? / Do you mean…? / If I understand correctly…',m1:'Sorry, could you repeat the last part, please?',m2:'Sorry, could you repeat the last part, please? Do you mean that I need to contact the client myself, or explain the situation to my manager first?',fr:'Demander une répétition ou une clarification est une compétence d’interaction, pas un échec.',q:['Which response is best?','I don’t understand.','Sorry, could you repeat the last part, please?','Again.'],a:1,ex:'Polite, specific clarification keeps the interaction professional.'},
 {type:'Part 2 · Opening a role-play',title:'Start with purpose instead of a long introduction',prompt:'You are calling IT because you cannot use essential software. Open the conversation.',plan:['Greeting','Reason for call','Impact','Request'],hint:'Hi, I’m calling because… I need… Would it be possible to…?',m1:'Hi, I’m calling because I need help with the reporting software. I have to use it today, but I cannot access one function. Could you help me?',m2:'Hi, I’m calling because I’m having a problem with the reporting software and I need to use it for a client update this afternoon. I can access the system, but I cannot generate the report. Could you help me check whether this is a permissions issue?',fr:'Dans une mise en situation, allez rapidement au but.',q:['Best first sentence?','I have many things to tell you.','Hi, I’m calling because I need help with the reporting software.','Software problem.'],a:1,ex:'The opening immediately establishes the purpose and gives the other person something to respond to.'},
 {type:'Part 2 · Information gathering',title:'Ask useful questions before proposing a solution',prompt:'A customer says “My order is wrong.” Ask questions that help you solve the problem.',plan:['Acknowledge','Order reference','What is wrong?','Urgency / desired solution'],hint:'Could you confirm…? / What exactly…? / When do you need…?',m1:'I’m sorry about that. Could you confirm your order number and tell me what is wrong with the delivery?',m2:'I’m sorry there’s a problem with the order. Could you give me the order reference and tell me whether the issue is the product, quantity or delivery? Also, do you need a replacement urgently, or would a refund be more appropriate?',fr:'Avant de proposer, récupérez les informations nécessaires.',q:['What is the strongest next move?','Promise a refund immediately.','Ask for the order reference and what is wrong.','Explain your company policy for five minutes.'],a:1,ex:'Good interaction starts with diagnosing the situation before choosing a solution.'},
 {type:'Part 2 · Problem solving',title:'Offer a realistic option and check acceptance',prompt:'A supplier cannot deliver the full order on time. Negotiate a partial solution.',plan:['Impact','Alternative','Specific detail','Check / confirm'],hint:'Could you send part…? / If you can…, that would allow us to… / Would that be possible?',m1:'The delay will affect production. Could you send part of the order tomorrow and the rest later? Would that be possible?',m2:'A full delay would stop part of our production, so I’d like to look at an alternative. Could you ship the most urgent 40% tomorrow and send the balance on the revised date? That would allow us to keep the critical line running. Would that be feasible from your side?',fr:'Proposez une solution concrète, expliquez pourquoi, puis demandez une réaction.',q:['Which is better interaction?','You need to deliver tomorrow.','Could you ship the most urgent 40% tomorrow and the balance later? Would that be feasible?','This is bad.'],a:1,ex:'The best answer is concrete, collaborative and invites the other person to respond.'},
 {type:'Part 2 · Complaint',title:'De-escalate without over-apologising',prompt:'A client is angry after repeated service errors. Take ownership and move towards action.',plan:['Acknowledge impact','Take ownership','Immediate action','Follow-up'],hint:'I understand why… / I’d like to take ownership… / The first step is…',m1:'I understand why you are frustrated. I want to help resolve this. I will review the problem today and confirm the next steps by email.',m2:'I understand why you’re frustrated, particularly because this has happened more than once. I’d like to take ownership of the case rather than ask you to repeat everything again. I’ll review the previous incidents today, confirm the immediate correction and send you a clear recovery plan with one point of contact.',fr:'Reconnaissez l’impact, puis passez vite à l’action concrète.',q:['Which phrase best de-escalates?','Calm down.','I understand why you’re frustrated, particularly because this has happened more than once.','It is not my department.'],a:1,ex:'It acknowledges the customer’s experience without arguing or becoming defensive.'},
 {type:'Part 2 · Procedure',title:'Give instructions in a logical order',prompt:'Explain to a new colleague how to escalate an urgent request.',plan:['First','Then','If…','Finally / check'],hint:'First… Next… If… Finally…',m1:'First, check the customer information. Then record the request and contact the person responsible. If they are unavailable, contact the duty supervisor. Finally, note the action in the system.',m2:'First, verify the customer details and identify why the request is urgent. Next, record the case in the system and contact the responsible person. If they are unavailable, escalate it to the duty supervisor rather than waiting. Finally, document the action and any deadline you have promised the customer.',fr:'Des connecteurs simples et précis sont essentiels pour expliquer une procédure.',q:['Which connector is best for a condition?','However','If','For example'],a:1,ex:'“If” introduces the alternative action when the normal person is unavailable.'},
 {type:'Part 2 · Negotiation',title:'Protect a boundary while remaining collaborative',prompt:'A client asks for a deadline you cannot safely promise.',plan:['Acknowledge need','State constraint','Offer alternative','Check priority'],hint:'I understand… I don’t want to promise… One option would be… Which element is most critical?',m1:'I understand you need it earlier, but I cannot confirm that date yet. One option is to deliver the most important part first. Which part is your priority?',m2:'I understand why the earlier date matters, but I don’t want to promise a deadline that we may not be able to meet reliably. One option would be to deliver the critical elements first and keep the remainder on the original schedule. Which deliverables are essential for you to have first?',fr:'Négocier ne signifie pas dire oui : expliquez la contrainte et créez une option.',q:['Best response?','Yes, no problem.','I can’t.','I don’t want to promise an unrealistic date. One option would be a phased delivery. Which elements are critical?'],a:2,ex:'The response protects reliability while keeping the negotiation constructive.'},
 {type:'Part 2 · Meeting interaction',title:'Clarify disagreement and move towards a decision',prompt:'Two people disagree strongly in a meeting. Intervene constructively.',plan:['Neutral summary','Identify criteria','Compare','Propose next step'],hint:'It sounds as though… Could we agree on…? Let’s compare…',m1:'It sounds like one option is faster and the other is safer. Could we agree which criterion is most important and compare the two options?',m2:'It sounds as though the disagreement is really about priorities: one proposal optimises speed, while the other reduces risk. Could we first agree on the decision criteria—time, cost and risk—and then compare both options against the same criteria? That may help us move towards a decision.',fr:'Reformulez le désaccord de manière neutre avant de chercher une décision.',q:['Best neutral sentence?','You are both wrong.','It sounds as though the disagreement is really about priorities.','Stop arguing.'],a:1,ex:'Neutral reformulation reduces tension and creates a basis for decision-making.'},
 {type:'Part 2 · Unexpected follow-up',title:'React when the examiner changes the situation',prompt:'You proposed Friday. The examiner says: “Friday is impossible. What else can you do?” Respond without repeating yourself.',plan:['Acknowledge new fact','Alternative','Consequence','Question'],hint:'In that case… Another option would be… Would Monday morning work?',m1:'In that case, we could try Monday morning. Would 9 a.m. work for you?',m2:'In that case, let’s look at another option. I could move the meeting to Monday morning and send the documents in advance so you can review them before we speak. Would 9 a.m. work, or would you prefer later in the morning?',fr:'Le rôle-play évolue : utilisez la nouvelle information au lieu de réciter votre première réponse.',q:['What should you do with new information?','Ignore it and repeat your plan.','Adapt your proposal.','Stop the conversation.'],a:1,ex:'The oral interview tests real-time interaction, so adapting matters.'},
 {type:'Part 3 · Opinion',title:'Give a position without stopping after “I agree”',prompt:'Do you think remote work is positive for companies?',plan:['Position','Reason 1','Reason 2 / limit','Example / conclusion'],hint:'Overall, I think… because… However… For example…',m1:'Overall, I think remote work can be positive because it gives flexibility and saves travel time. However, teams still need regular contact because communication can become more difficult.',m2:'Overall, I think remote work can be positive when it is structured well. It can improve flexibility and reduce commuting time, which may help concentration and retention. However, it can also weaken informal communication and make onboarding harder. For that reason, I prefer a hybrid approach with clear expectations and regular team contact.',fr:'Une opinion forte = position + raisons + nuance + exemple ou conclusion.',q:['Which answer shows discussion skill?','Yes.','Yes, because it is good.','Overall, I think it can be positive because of flexibility, although teams still need regular contact.'],a:2,ex:'A balanced answer gives a position and shows nuance.'},
 {type:'Part 3 · Pros and cons',title:'Compare two sides naturally',prompt:'Discuss advantages and disadvantages of using AI at work.',plan:['Advantage','Example','Risk','Balanced view'],hint:'On the one hand… On the other hand… The key is…',m1:'AI can save time on repetitive tasks, but it can also make mistakes. Companies should use it with human checks.',m2:'On the one hand, AI can save significant time on repetitive analysis, drafting and information retrieval. On the other hand, it can produce incorrect information and may create confidentiality risks. In my view, the key is to use it as a support tool while keeping human review for important decisions.',fr:'Les connecteurs d’opposition et une conclusion nuancée donnent de la structure.',q:['Best balancing phrase?','AI is always good.','On the one hand… on the other hand…','AI, AI, AI.'],a:1,ex:'The pair clearly signals a balanced discussion.'},
 {type:'Part 3 · Give an example',title:'Turn an abstract point into evidence',prompt:'You say communication is important in teamwork. Give a concrete example.',plan:['General point','Example situation','Action','Impact'],hint:'For example, on a recent project… This helped us…',m1:'For example, on a recent project we had a short meeting every week. This helped everyone understand the priorities and problems.',m2:'For example, on a recent project several teams were depending on the same information. We introduced a short weekly coordination meeting and a shared action list. That simple routine made responsibilities clearer and allowed us to identify delays before they became serious.',fr:'Un exemple concret prouve que vous pouvez développer votre idée.',q:['What makes an example strong?','It is unrelated but long.','It shows a real situation and the impact.','It uses difficult vocabulary only.'],a:1,ex:'A useful example connects directly to the point and shows why it matters.'},
 {type:'Part 3 · Recommend',title:'Make a recommendation and justify it',prompt:'A company has too many unproductive meetings. What would you recommend?',plan:['Problem','Recommendation','Why','Practical rule'],hint:'I would recommend… because… One simple rule would be…',m1:'I would recommend reducing meetings that only share information. Those updates can be sent in writing. Meetings should have a clear objective and agenda.',m2:'I would recommend distinguishing between information-sharing and genuine collaboration. Routine updates can usually be sent asynchronously, while meetings should be reserved for decisions, problem-solving or discussion. One simple rule would be that every meeting invitation states the objective, required participants and expected decision or output.',fr:'Une recommandation doit être pratique, pas seulement une opinion.',q:['Strongest recommendation?','Have fewer meetings.','I would recommend reserving meetings for decisions and problem-solving, with a clear objective on every invitation.','Meetings are bad.'],a:1,ex:'It gives a concrete action and explains the principle behind it.'},
 {type:'Fluency · Repair',title:'Correct yourself without losing momentum',prompt:'You make a tense or vocabulary mistake while speaking. Practise repairing and continuing.',plan:['Signal repair','Correct','Continue idea','Do not apologise repeatedly'],hint:'Sorry, I meant… / Let me rephrase that… / What I mean is…',m1:'We deliver—sorry, we delivered the project last Friday, and the client was satisfied.',m2:'The project was eventually—let me rephrase that—the project was finally delivered on Friday, two days later than planned, but we kept the client informed throughout the delay.',fr:'Une auto-correction rapide est préférable à s’arrêter complètement.',q:['Best repair phrase?','Sorry sorry sorry.','Let me rephrase that.','I cannot speak English.'],a:1,ex:'A short repair phrase lets you correct the message and continue confidently.'},
 {type:'Interaction · Return the ball',title:'Finish your turn in a way that invites interaction',prompt:'You have proposed a solution in a role-play. Keep the exchange going.',plan:['Summarise','Check','Question','Listen'],hint:'Would that work for you? / How does that sound? / Which option would you prefer?',m1:'I can send the replacement today. Would that work for you?',m2:'I can release the replacement today and email you the tracking details as soon as it is dispatched. Would that solution work for you, or would you prefer a refund instead?',fr:'Un bon candidat ne parle pas seul : il invite l’interlocuteur à répondre.',q:['Which ending invites interaction?','That is all.','Would that solution work for you?','I have finished.'],a:1,ex:'A check question naturally passes the conversation back to the interlocutor.'}
];

function escapeHTML(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function speak(text, accent='GB'){
  if(!('speechSynthesis' in window)){alert('Speech synthesis is not available in this browser.');return;}
  speechSynthesis.cancel();
  const u=new SpeechSynthesisUtterance(text); u.rate=.92; u.pitch=1;
  const target={GB:'en-GB',US:'en-US',AU:'en-AU'}[accent]||'en-GB';
  const voices=speechSynthesis.getVoices();
  u.voice=voices.find(v=>v.lang===target)||voices.find(v=>v.lang.startsWith('en'))||null;
  u.lang=target; speechSynthesis.speak(u);
}
function initToolkit(){
  $('#toolkitGrid').innerHTML=toolkit.map(t=>`<article class="tool-card"><div class="tool-icon">${t.icon}</div><h3>${t.title}</h3><ul>${t.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="audio-row"><button data-speak="${escapeHTML(t.items.join(' '))}" data-accent="GB">🔊 UK</button><button data-speak="${escapeHTML(t.items.join(' '))}" data-accent="US">🔊 US</button><button data-speak="${escapeHTML(t.items.join(' '))}" data-accent="AU">🔊 AU</button></div></article>`).join('');
}
function initScenarioFilters(){
 const sectors=[...new Set(scenarios.map(s=>s.sector))].sort();
 $('#scenarioSector').insertAdjacentHTML('beforeend',sectors.map(s=>`<option value="${escapeHTML(s)}">${s}</option>`).join(''));
 ['scenarioStage','scenarioSector','scenarioSearch'].forEach(id=>$('#'+id).addEventListener('input',renderScenarios));
 renderScenarios();
}
function stageLabel(stage){return stage==='intro'?'Part 1 · Introduction':stage==='roleplay'?'Part 2 · Role-play':'Part 3 · Discussion';}
function renderScenarios(){
 const st=$('#scenarioStage').value, sec=$('#scenarioSector').value, q=$('#scenarioSearch').value.toLowerCase().trim();
 const list=scenarios.filter(s=>(st==='all'||s.stage===st)&&(sec==='all'||s.sector===sec)&&(!q||`${s.title} ${s.prompt} ${s.sector} ${s.follow.join(' ')}`.toLowerCase().includes(q)));
 $('#scenarioCount').textContent=`${list.length} scenario${list.length===1?'':'s'}`;
 $('#scenarioLibrary').innerHTML=list.map(s=>`<details class="scenario-card"><summary><span class="scenario-icon">${s.stage==='intro'?'1':s.stage==='roleplay'?'2':'3'}</span><span class="scenario-meta"><b>${escapeHTML(s.title)}</b><small>${stageLabel(s.stage)} · ${escapeHTML(s.sector)}</small></span><span class="scenario-tags"><span>${s.level}</span></span></summary><div class="scenario-body"><div class="scenario-prompt"><b>Examiner prompt</b><p>${escapeHTML(s.prompt)}</p></div><b>Possible follow-ups</b><div class="followups">${s.follow.map(f=>`<span>${escapeHTML(f)}</span>`).join('')}</div><div class="scenario-actions"><button data-scenario-model="${s.id}" data-level="1">Model 1 · accessible</button><button data-scenario-model="${s.id}" data-level="2">Model 2 · stronger</button><button data-speak="${escapeHTML(s.prompt)}" data-accent="GB">🔊 Examiner prompt</button></div><div class="model-panel" id="model-${s.id}"></div></div></details>`).join('')||'<p>No scenarios match this filter.</p>';
}

function renderGuidedNav(){
 $('#guidedNav').innerHTML=guidedTasks.map((t,i)=>`<button data-guide-index="${i}" class="${i===state.guidedIndex?'active':''}">${String(i+1).padStart(2,'0')} · ${t.title}</button>`).join('');
}
function renderGuided(){
 const t=guidedTasks[state.guidedIndex]; renderGuidedNav();
 $('#guidedTaskHost').innerHTML=`<article class="guided-task"><span class="task-type">${escapeHTML(t.type)} · TASK ${state.guidedIndex+1}/${guidedTasks.length}</span><h3>${escapeHTML(t.title)}</h3><div class="prompt-quote"><b>Your speaking prompt</b><p>${escapeHTML(t.prompt)}</p></div><div class="response-plan">${t.plan.map((p,i)=>`<span><b>${i+1}</b><br>${escapeHTML(p)}</span>`).join('')}</div><div class="micro-grid">${t.q.slice(1).map((o,i)=>`<button class="micro-choice" data-choice="${i}">${escapeHTML(o)}</button>`).join('')}</div><div class="micro-feedback" id="microFeedback"></div><div class="task-tool-row"><button class="primary" data-toggle-panel="hintPanel">Hint</button><button data-toggle-panel="answerModels">Models</button><button data-toggle-panel="coachCheck">Self-check</button><button data-speak="${escapeHTML(t.prompt)}" data-accent="GB">🔊 Hear prompt</button></div><div class="hint-panel" id="hintPanel"><b>Hint</b><p>${escapeHTML(t.hint)}</p><div class="fr-coach">${escapeHTML(t.fr)}</div></div><div class="answer-models" id="answerModels"><div class="model-choice"><button data-guide-model="1">Model 1 · accessible</button><button data-guide-model="2">Model 2 · stronger</button><button data-guide-audio="GB">🔊 UK</button><button data-guide-audio="US">🔊 US</button><button data-guide-audio="AU">🔊 AU</button></div><div class="answer-model-text" id="guideModelText">Choose a model level after you try.</div></div><div class="coach-check" id="coachCheck"><b>Listen to yourself. Did you…</b><div class="self-rubric"><label><input type="checkbox"> answer directly?</label><label><input type="checkbox"> add detail?</label><label><input type="checkbox"> give an example/action?</label><label><input type="checkbox"> stay understandable?</label><label><input type="checkbox"> keep interaction moving?</label></div></div><div class="record-box"><button class="record-btn" data-record-key="guided-${state.guidedIndex}" type="button">● Record my answer</button><span class="record-status">Optional local recording</span><div class="record-playback"></div></div><div class="task-actions"><button class="small-button" id="prevGuide" ${state.guidedIndex===0?'disabled':''}>← Previous</button><button class="small-button primary" id="nextGuide">${state.guidedIndex===guidedTasks.length-1?'Finish guided lab':'Next task →'}</button></div></article>`;
}

let activeRecorder=null, activeStream=null, activeChunks=[], activeKey=null;
async function toggleRecord(btn, playback){
  if(activeRecorder && activeRecorder.state==='recording'){
    activeRecorder.stop(); return;
  }
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true});
    activeStream=stream; activeChunks=[]; activeKey=btn.dataset.recordKey||btn.id||'recording';
    const rec=new MediaRecorder(stream); activeRecorder=rec;
    rec.ondataavailable=e=>{if(e.data.size) activeChunks.push(e.data);};
    rec.onstop=()=>{
      const blob=new Blob(activeChunks,{type:rec.mimeType||'audio/webm'}); const url=URL.createObjectURL(blob);
      playback.innerHTML=`<audio class="record-playback" controls src="${url}"></audio> <a class="record-download" href="${url}" download="cloe-oral-practice.webm">Save recording</a>`;
      btn.textContent='● Record again'; btn.classList.remove('recording');
      const st=btn.parentElement.querySelector('.record-status'); if(st) st.textContent='Recording ready for playback';
      stream.getTracks().forEach(t=>t.stop()); activeRecorder=null; activeStream=null;
    };
    rec.start(); btn.textContent='■ Stop recording'; btn.classList.add('recording');
    const st=btn.parentElement.querySelector('.record-status'); if(st) st.textContent='Recording… speak naturally';
  }catch(e){ alert('Microphone access is unavailable. You can still complete the speaking task aloud and use the models.'); }
}

function rand(arr){return arr[Math.floor(Math.random()*arr.length)];}
function buildMock(){
 const intro=scenarios.filter(s=>s.stage==='intro');
 const role=scenarios.filter(s=>s.stage==='roleplay');
 const disc=scenarios.filter(s=>s.stage==='discussion');
 const selectedIntro=[...intro].sort(()=>Math.random()-.5).slice(0,3);
 const r=rand(role), d=rand(disc);
 const prompts=[
  ...selectedIntro.map((s,i)=>({stage:1,label:`Introduction ${i+1}`,text:s.prompt,model:s.m2,scenario:s})),
  {stage:2,label:'Role-play · opening',text:r.prompt,model:r.m2,scenario:r},
  ...r.follow.map((f,i)=>({stage:2,label:`Role-play · follow-up ${i+1}`,text:f,model:r.m2,scenario:r})),
  {stage:3,label:'Discussion · opening',text:d.prompt,model:d.m2,scenario:d},
  ...d.follow.map((f,i)=>({stage:3,label:`Discussion · follow-up ${i+1}`,text:f,model:d.m2,scenario:d}))
 ];
 state.mock={prompts,intro:selectedIntro,role:r,discussion:d}; state.mockIndex=0; state.mockSeconds=1080;
}
function updateMockTabs(stage){ [1,2,3].forEach(n=>$('#stageTab'+n).classList.toggle('active',n===stage)); }
function renderMockPrompt(){
 const p=state.mock.prompts[state.mockIndex]; updateMockTabs(p.stage);
 $('#mockPromptArea').innerHTML=`<div class="examiner-line"><div class="examiner-avatar">E</div><div><small>${escapeHTML(p.label)}</small><p>${escapeHTML(p.text)}</p></div></div><div class="fr-coach">Répondez d’abord directement. Développez ensuite. Dans les parties 2 et 3, faites vivre l’interaction.</div><small>${state.mockIndex+1} / ${state.mock.prompts.length}</small>`;
 $('#nextMockPrompt').textContent=state.mockIndex===state.mock.prompts.length-1?'Finish interview':'Next prompt →';
 $('#mockPlayback').innerHTML='';
}
function startMock(){
 buildMock(); $('#mockLanding').classList.add('hidden'); $('#mockReview').classList.add('hidden'); $('#mockLive').classList.remove('hidden'); renderMockPrompt();
 clearInterval(state.mockTimerId); state.mockTimerId=setInterval(()=>{state.mockSeconds=Math.max(0,state.mockSeconds-1); updateMockTimer(); if(state.mockSeconds===0){finishMock();}},1000); updateMockTimer();
}
function updateMockTimer(){
 const m=Math.floor(state.mockSeconds/60),s=state.mockSeconds%60; $('#mockTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
 const pct=state.mockSeconds/1080*100; $('#mockTrack').style.width=pct+'%'; $('#mockTrack').style.background=pct<25?'var(--red)':pct<50?'var(--yellow)':'var(--green)';
}
function finishMock(){
 clearInterval(state.mockTimerId); $('#mockLive').classList.add('hidden'); $('#mockReview').classList.remove('hidden');
 $('#readinessGrid').innerHTML=['Vocabulary','Grammar & syntax','Fluency','Pronunciation & intonation','Interaction'].map((x,i)=>`<label><b>${x}</b><br><select data-readiness="${i}"><option value="">Choose…</option><option>Ready</option><option>Developing</option><option>Needs practice</option></select></label>`).join('');
 markComplete(5);
}
function renderMockModels(){
 const m=state.mock; $('#mockModels').classList.remove('hidden');
 $('#mockModels').innerHTML=`<div class="formats-masterclass"><h3>Model responses for this mock</h3><p><b>Part 1</b> — models show how to develop a professional answer, not a script to memorise.</p>${m.intro.map(s=>`<article class="model-panel show"><h4>${escapeHTML(s.title)}</h4><p>${escapeHTML(s.m2)}</p><div class="audio-row"><button data-speak="${escapeHTML(s.m2)}" data-accent="GB">🔊 UK model</button></div></article>`).join('')}<p><b>Part 2 · ${escapeHTML(m.role.title)}</b></p><article class="model-panel show"><p>${escapeHTML(m.role.m2)}</p><div class="audio-row"><button data-speak="${escapeHTML(m.role.m2)}" data-accent="GB">🔊 UK model</button></div></article><p><b>Part 3 · ${escapeHTML(m.discussion.title)}</b></p><article class="model-panel show"><p>${escapeHTML(m.discussion.m2)}</p><div class="audio-row"><button data-speak="${escapeHTML(m.discussion.m2)}" data-accent="GB">🔊 UK model</button></div></article></div>`;
}
function markComplete(n){state.completed.add(Number(n)); const pct=Math.round(state.completed.size/5*100); $('#progressLabel').textContent=`${pct}% complete`; $('#headerProgress').style.width=pct+'%'; $$(`[data-complete="${n}"]`).forEach(b=>{b.classList.add('done');b.textContent='✓ Completed';}); localStorage.setItem('cloeL7Completed',JSON.stringify([...state.completed]));}
function loadProgress(){try{(JSON.parse(localStorage.getItem('cloeL7Completed'))||[]).forEach(markComplete);}catch(e){}}
function downloadReport(){
 const readiness=$$('[data-readiness]').map(s=>s.value||'Not selected');
 const lines=['CLOE Success Path · Lesson 7 · Oral Interaction & Interview','',`Lesson progress: ${Math.round(state.completed.size/5*100)}%`,'', 'Mock scenarios:'];
 if(state.mock){lines.push(`Part 1: ${state.mock.intro.map(x=>x.title).join(' / ')}`,`Part 2: ${state.mock.role.title}`,`Part 3: ${state.mock.discussion.title}`);}
 lines.push('','Self-review:','Vocabulary: '+readiness[0],'Grammar & syntax: '+readiness[1],'Fluency: '+readiness[2],'Pronunciation & intonation: '+readiness[3],'Interaction: '+readiness[4],'','Next practice: repeat the scenario that felt least natural, then try a new random mock.');
 const blob=new Blob([lines.join('\n')],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='CLOE_Lesson_07_Oral_Report.txt';a.click();URL.revokeObjectURL(url);
}

function attachGlobalEvents(){
 document.addEventListener('click',e=>{
   const scroll=e.target.closest('[data-scroll]'); if(scroll){$(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}
   const done=e.target.closest('[data-complete]'); if(done) markComplete(done.dataset.complete);
   const sp=e.target.closest('[data-speak]'); if(sp) speak(sp.dataset.speak,sp.dataset.accent||'GB');
   const sm=e.target.closest('[data-scenario-model]'); if(sm){const s=scenarios.find(x=>x.id===sm.dataset.scenarioModel),panel=$('#model-'+s.id); panel.classList.add('show'); panel.innerHTML=`<h4>${sm.dataset.level==='1'?'Model 1 · accessible':'Model 2 · stronger'}</h4><p>${escapeHTML(sm.dataset.level==='1'?s.m1:s.m2)}</p><div class="audio-row"><button data-speak="${escapeHTML(sm.dataset.level==='1'?s.m1:s.m2)}" data-accent="GB">🔊 UK</button><button data-speak="${escapeHTML(sm.dataset.level==='1'?s.m1:s.m2)}" data-accent="US">🔊 US</button><button data-speak="${escapeHTML(sm.dataset.level==='1'?s.m1:s.m2)}" data-accent="AU">🔊 AU</button></div>`;}
   const gi=e.target.closest('[data-guide-index]'); if(gi){state.guidedIndex=Number(gi.dataset.guideIndex);renderGuided();}
   const tp=e.target.closest('[data-toggle-panel]'); if(tp) $('#'+tp.dataset.togglePanel)?.classList.toggle('show');
   const gm=e.target.closest('[data-guide-model]'); if(gm){const t=guidedTasks[state.guidedIndex]; $('#guideModelText').textContent=gm.dataset.guideModel==='1'?t.m1:t.m2; $('#guideModelText').dataset.active=gm.dataset.guideModel;}
   const ga=e.target.closest('[data-guide-audio]'); if(ga){const t=guidedTasks[state.guidedIndex],lvl=$('#guideModelText').dataset.active||'2'; speak(lvl==='1'?t.m1:t.m2,ga.dataset.guideAudio);}
   const mc=e.target.closest('.micro-choice'); if(mc){const t=guidedTasks[state.guidedIndex],choice=Number(mc.dataset.choice); $$('.micro-choice').forEach((b,i)=>{b.disabled=true;if(i===t.a)b.classList.add('correct');}); if(choice!==t.a) mc.classList.add('wrong'); const f=$('#microFeedback');f.className='micro-feedback show '+(choice===t.a?'good':'bad');f.innerHTML=`<b>${choice===t.a?'Correct thinking':'Try this thinking instead'}</b><br>${escapeHTML(t.ex)}`;}
   const rec=e.target.closest('.record-btn'); if(rec){const box=rec.closest('.record-box'),playback=box.querySelector('.record-playback')||$('#mockPlayback');toggleRecord(rec,playback);}
 });
 $('#guidedTaskHost').addEventListener('click',e=>{if(e.target.id==='prevGuide'){state.guidedIndex=Math.max(0,state.guidedIndex-1);renderGuided();}if(e.target.id==='nextGuide'){if(state.guidedIndex<guidedTasks.length-1){state.guidedIndex++;renderGuided();}else{markComplete(4);$('#realDeal').scrollIntoView({behavior:'smooth'});}}});
 $('#toggleFrench').addEventListener('click',()=>{document.body.classList.toggle('fr-hidden');const on=!document.body.classList.contains('fr-hidden');$('#toggleFrench').setAttribute('aria-pressed',String(on));$('#toggleFrench').textContent=on?'FR Coach ✓':'FR Coach';});
 $('#resetAll').addEventListener('click',()=>{if(confirm('Reset Lesson 7 progress?')){localStorage.removeItem('cloeL7Completed');location.reload();}});
 $('#openCoach').addEventListener('click',()=>$('#coachDialog').showModal());
 $('#startMock').addEventListener('click',startMock);
 $('#repeatPrompt').addEventListener('click',()=>speak(state.mock.prompts[state.mockIndex].text,'GB'));
 $('#nextMockPrompt').addEventListener('click',()=>{if(state.mockIndex<state.mock.prompts.length-1){state.mockIndex++;renderMockPrompt();}else finishMock();});
 $('#showMockModels').addEventListener('click',renderMockModels);
 $('#downloadReport').addEventListener('click',downloadReport);
 $('#restartMock').addEventListener('click',()=>{clearInterval(state.mockTimerId);$('#mockModels').classList.add('hidden');$('#mockReview').classList.add('hidden');$('#mockLanding').classList.remove('hidden');$('#mockTimer').textContent='18:00';$('#mockTrack').style.width='100%';});
 $('#mockRecord').dataset.recordKey='final-mock';
}
function initClock(){setInterval(()=>{state.lessonSeconds++;const m=Math.floor(state.lessonSeconds/60),s=state.lessonSeconds%60;$('#lessonClock').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;},1000);}
function init(){initToolkit();initScenarioFilters();renderGuided();attachGlobalEvents();loadProgress();initClock();}
document.addEventListener('DOMContentLoaded',init);
